      "name": "Domestic Critical Minerals & Mining",
      "impact": "tailwind",
      "rationale": "Direct government capital injections and offtake commitments accelerate revenue growth for U.S.-focused miners and processors."
    },
    {
      "name": "Advanced Battery Materials",
      "impact": "tailwind",
      "rationale": "$1.4B investment in Sila Nanotechnologies boosts domestic silicon anode and Li-ion battery cell production, challenging Asian dominance."
    },
    {
      "name": "Defense & Aerospace Supply Chain",
      "impact": "tailwind",
      "rationale": "On-shoring of scandium, bauxite, and magnets secures critical inputs for fighter jets and munitions, reducing geopolitical supply risk."
    },
    {
      "name": "Global Rare Earth & Graphite Producers (ex-US aligned)",
      "impact": "headwind",
      "rationale": "U.S. policy explicitly aims to reduce dependency on foreign sources, threatening long-term demand for non-aligned international suppliers."
    },
    {
      "name": "Mining Equipment & Services",
      "impact": "tailwind",
      "rationale": "A new generation of domestic mines and processing facilities, plus workforce expansion, will drive demand for heavy equipment and engineering services."
    }
  ],
